import { timestamp, uuid } from "drizzle-orm/pg-core";

/** UUID primary key generated by Postgres. */
export const id = () => uuid("id").primaryKey().defaultRandom();

export const createdAt = () =>
  timestamp("created_at", { withTimezone: true }).notNull().defaultNow();

/** Maintained by the app.set_updated_at() trigger (see the functions migration). */
export const updatedAt = () =>
  timestamp("updated_at", { withTimezone: true }).notNull().defaultNow();

/** Money: numeric(12,2). Drizzle returns numeric as string to avoid float rounding. */
export const money = { precision: 12, scale: 2 } as const;
